#include <iostream>

class Coord {
    int m_v;
public:
    Coord(int v) : m_v{v} {}

    Coord(const Coord& src) : m_v{src.m_v} {
        std::cout << "copy " << m_v << "\n";
    }

    int v() const { return m_v; }
};

Coord make(int v) {
    return Coord{v};
}

int main() {
    int n;
    std::cin >> n;
    for (int i = 0; i < n; ++i) {
        int v;
        std::cin >> v;
        Coord a = make(v);
        Coord b = a;
        std::cout << "value " << b.v() << "\n";
    }
}

